import type { GraftabilityIssue } from './types'

export interface UnsupportedMemberAlertModel {
  headline: string
  typeLabels: string[]
  description: string
}

const FILTER_HINT_SINGLE = 'Please change this method to return supported type, or apply filter in your gg command.'
const FILTER_HINT_MULTIPLE = 'Please change this method to use supported types, or apply filter in your gg command.'

function collectUniqueTypeLabels(issues: GraftabilityIssue[]): string[] {
  const labels: string[] = []
  const seen = new Set<string>()

  for (const issue of issues) {
    const label = issue.typeLabel?.trim()
    if (!label || seen.has(label)) {
      continue
    }
    seen.add(label)
    labels.push(label)
  }

  return labels
}

function buildHeadline(issues: GraftabilityIssue[], uniqueTypeCount: number): string {
  const hasReturn = issues.some((issue) => issue.memberKind === 'return')
  const hasParameter = issues.some(
    (issue) => issue.memberKind === 'parameter' || issue.memberKind === 'constructor-parameter'
  )

  if (uniqueTypeCount > 1 || (hasReturn && hasParameter)) {
    return 'This method returns and uses unsupported types:'
  }

  if (hasReturn) {
    return 'This method returns unsupported type:'
  }

  return 'This member uses unsupported type:'
}

export function getUnsupportedMemberAlertModel(issues: GraftabilityIssue[]): UnsupportedMemberAlertModel | null {
  if (issues.length === 0) {
    return null
  }

  const typeLabels = collectUniqueTypeLabels(issues)
  if (typeLabels.length === 0) {
    return null
  }

  const headline = buildHeadline(issues, typeLabels.length)
  const description = typeLabels.length > 1 ? FILTER_HINT_MULTIPLE : FILTER_HINT_SINGLE

  return {
    headline,
    typeLabels,
    description,
  }
}

export function formatNonGraftableCallablesMessage(count: number): string {
  const label = count === 1 ? 'method' : 'methods'
  return `${count} ${label} can't be included in the Graft - they use unsupported types`
}
