'use client'

import { create } from 'zustand'
import { devtools } from 'zustand/middleware'

import { VisionStoreDevtoolsName } from '../vision-store-names.const'

import { createCodeActions } from './code.actions'
import { codeInitialState } from './code.slice'
import type { CodeStore } from './code.type'

export const useCodeStore = create<CodeStore>()(
  devtools(
    (set) => ({
      ...codeInitialState,
      ...createCodeActions(set),
    }),
    { name: VisionStoreDevtoolsName.Code }
  )
)
