import { MethodDetailItemRow } from '@/core/components/MethodDetailItemRow'
import { MethodInfoBlock } from '@/core/components/MethodInfoBlock'
import type { CommentThrowDoc } from '@/core/types/comment-doc.type'
import { METHOD_THROWS_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodThrows.module.scss'

interface MethodThrowsProps {
  throws: CommentThrowDoc[]
}

export function MethodThrows({ throws }: MethodThrowsProps) {
  if (throws.length === 0) {
    return null
  }

  return (
    <div data-testid={METHOD_THROWS_TEST_IDS.root}>
      <MethodInfoBlock title="Throws" layout="full" contentSurface={false}>
        <div className={styles.list}>
          {throws.map((item) => (
            <MethodDetailItemRow
              key={`${item.rawType}-${item.description ?? ''}`}
              typeName={item.rawType}
              description={item.description}
            />
          ))}
        </div>
      </MethodInfoBlock>
    </div>
  )
}
