import { formatExecutionResult } from '@/core/libraries-runtime/formatExecutionResult'
import { runMemberInvocation } from '@/core/libraries-runtime/runMemberInvocation'
import { unpackInvocationResult } from '@/core/libraries-runtime/unpackInvocationResult'
import type {
  ExecuteMemberParams,
  ExecutionParams,
  FieldExecutionParams,
  InstanceParams,
} from '@/core/types/library.type'
import { getContext } from '@/core/utils/hypertube/getContext'

import type { LibraryActions, LibraryGet, LibrarySet, LibraryStore } from './libraries.type'
import {
  appendLog,
  formatActionLog,
  formatExecutionError,
  formatInstanceLog,
  formatResultLogLine,
  getTypeContext,
  isGlobalMember,
  needsInstance,
} from './libraries.utils'

export const createLibraryActions = (set: LibrarySet, get: LibraryGet): LibraryActions => {
  const executeMember = async ({
    runtimeName,
    classData,
    member,
    resultKey,
    methodParams = [],
    instanceParams = [],
    constructorKey,
  }: ExecuteMemberParams) => {
    const { gatewayPath, gatewayWsPort, isSecured } = get()

    try {
      const runtimeContext = await getContext({
        runtimeName,
        gatewayPath,
        gatewayPort: gatewayWsPort,
        isSecured,
      })

      const typeContext = isGlobalMember(member) ? undefined : getTypeContext(runtimeContext, runtimeName, classData)

      if (needsInstance(member)) {
        set((state: LibraryStore) => ({
          ...state,
          logs: appendLog(state, resultKey, formatInstanceLog(classData.name, constructorKey, instanceParams)),
        }))
      }

      const actionLog = formatActionLog(member, methodParams)
      if (actionLog) {
        set((state: LibraryStore) => ({
          ...state,
          logs: appendLog(state, resultKey, actionLog),
        }))
      }

      const execution = await runMemberInvocation({
        runtimeContext,
        typeContext,
        member,
        methodParams,
        instanceParams,
        constructorKey,
      })

      const unpacked = await unpackInvocationResult(execution, {
        libraries: get().libraries,
        fallbackClassData: member.kind === 'constructor' ? classData : undefined,
        hintTypeName:
          member.kind === 'method'
            ? member.method.returns
            : member.kind === 'field'
              ? member.field.fieldType
              : undefined,
      })
      const resultValue = formatExecutionResult(unpacked)

      set((state: LibraryStore) => ({
        ...state,
        results: {
          ...state.results,
          [resultKey]: resultValue,
        },
        logs: appendLog(state, resultKey, formatResultLogLine(resultValue)),
      }))
    } catch (error) {
      set((state: LibraryStore) => ({
        ...state,
        logs: appendLog(state, resultKey, formatExecutionError(error)),
      }))
    }
  }

  return {
    executeMember,

    executeField: ({ runtimeName, classData, field, instanceParams = [], constructorKey }: FieldExecutionParams) =>
      executeMember({
        runtimeName,
        classData,
        member: { kind: 'field', field },
        resultKey: `field-${field.name}`,
        instanceParams,
        constructorKey,
      }),

    executeMethod: ({
      runtimeName,
      classData,
      methodData,
      methodKey,
      isStatic,
      params,
      instanceParams,
      constructorKey,
    }: ExecutionParams) =>
      executeMember({
        runtimeName,
        classData,
        member: { kind: 'method', method: methodData, methodKey, isStatic },
        resultKey: methodKey,
        methodParams: params,
        instanceParams,
        constructorKey,
      }),

    executeConstructor: ({ runtimeName, classData, instanceParams, constructorKey }: InstanceParams) =>
      executeMember({
        runtimeName,
        classData,
        member: { kind: 'constructor' },
        resultKey: constructorKey ?? classData.name,
        instanceParams,
        constructorKey,
      }),

    clearResult: (name: string) => {
      set((state: LibraryStore) => ({
        ...state,
        results: {
          ...state.results,
          [name]: '',
        },
        logs: {
          ...state.logs,
          [name]: [],
        },
      }))
    },
  }
}
