import { UnifiedGraftModelType } from '@graftcode/protocol'

/**
 * Re-export the protocol enum. We use the enum's KEY names (strings) for comparisons, not the numeric values.
 * UnifiedGraftModelTypeKey provides those key strings so we compare getUnifiedGraftModelType(node) === UnifiedGraftModelTypeKey.TYPE_DEF.
 */
export { UnifiedGraftModelType }

/** Enum key names as strings (the enum's key names, not values). Use for comparisons with getUnifiedGraftModelType(). */
const enumKeys = (Object.keys(UnifiedGraftModelType) as (keyof typeof UnifiedGraftModelType)[]).filter(
  (k) => typeof UnifiedGraftModelType[k] === 'number'
)
export const UnifiedGraftModelTypeKey = Object.fromEntries(enumKeys.map((k) => [k, k])) as {
  [K in (typeof enumKeys)[number]]: K
}

export type UnifiedGraftModelKey = (typeof UnifiedGraftModelTypeKey)[keyof typeof UnifiedGraftModelTypeKey]

type ProtocolKey = keyof typeof UnifiedGraftModelType

function isTypeUsageNodeKindKey(key: ProtocolKey): boolean {
  return typeof UnifiedGraftModelType[key] === 'number' && key.startsWith('TYPE_USAGE_')
}

const typeUsageNodeKindKeys = (Object.keys(UnifiedGraftModelType) as ProtocolKey[]).filter(isTypeUsageNodeKindKey)

/** TYPE_USAGE_* keys from protocol; use for comparison with getUnifiedGraftModelType(node). */
export const TYPE_USAGE_NODE_KIND = Object.fromEntries(typeUsageNodeKindKeys.map((k) => [k, k])) as {
  [K in (typeof typeUsageNodeKindKeys)[number]]: K
}

export type TypeUsageNodeKind = (typeof TYPE_USAGE_NODE_KIND)[keyof typeof TYPE_USAGE_NODE_KIND]

/** Member type keys in TYPE_DEF (excludes GENERIC_PARAMETERS, etc.). Uses enum key strings. */
export const MEMBER_IDS = [
  UnifiedGraftModelTypeKey.TYPE_DEF,
  UnifiedGraftModelTypeKey.CONSTRUCTOR,
  UnifiedGraftModelTypeKey.OVERLOADED_CONSTRUCTOR,
  UnifiedGraftModelTypeKey.INSTANCE_FIELD,
  UnifiedGraftModelTypeKey.STATIC_FIELD,
  UnifiedGraftModelTypeKey.INSTANCE_METHOD,
  UnifiedGraftModelTypeKey.STATIC_METHOD,
  UnifiedGraftModelTypeKey.OVERLOADED_INSTANCE_METHOD,
  UnifiedGraftModelTypeKey.OVERLOADED_STATIC_METHOD,
  UnifiedGraftModelTypeKey.PROPERTY,
] as const

/** Member types in TYPE_DEF. String keys only. */
export const MEMBER_TYPES = new Set<string>(MEMBER_IDS)

/**
 * Unified Graft Model payload indices – single source of truth.
 * Matches @graftcode/protocol and graft-model.types.ts / graft-model-with-type-usage.data.ts.
 */

/** LIBRARY: [LIBRARY_GROUP_ID, LIBRARY_NAME, LIBRARY_VERSION, RUNTIME_NAME, GMA_UGM_VERSION, TYPE_DEF, ...] */
export const LIBRARY = {
  GROUPID: 0,
  NAME: 1,
  VERSION: 2,
  TYPEDEFS_FROM: 3,
} as const

/** TYPE_DEF: [NAMESPACE, TYPENAME, MODULE_FULLNAME, MODULE_HASH, MODIFIER, GENERIC_PARAMETERS?, ...members] */
export const TYPE_DEF = {
  NAMESPACE: 0,
  TYPENAME: 1,
  MODULE_FULLNAME: 2,
  MODIFIER: 4,
  MEMBERS_FROM: 5,
} as const

/** METHOD: [NAME, TYPE_USAGE (return), MODIFIER, PARAMETERS_ARRAY] */
export const METHOD = {
  NAME: 0,
  RETURN_TYPE: 1,
  MODIFIER: 2,
  PARAMETERS: 3,
} as const

/** CONSTRUCTOR: [CLASS_NAME, MODIFIER, PARAMETERS_ARRAY] */
export const CONSTRUCTOR = {
  CLASS_NAME: 0,
  MODIFIER: 1,
  PARAMETERS: 2,
} as const

/** FIELD: [NAME, TYPE_USAGE, MODIFIER, CLASS_NAME] */
export const FIELD = {
  NAME: 0,
  TYPE_USAGE: 1,
  MODIFIER: 2,
  DECLARING_TYPE: 3,
} as const

/** PARAMETER: [TYPE_USAGE, NAME] */
