/**
 * Compute tree expanded items from navigation path
 * E.g., path ['Lib', 'Class'] → ['root', 'Lib', 'Lib/Class']
 */
export const computeExpandedFromPath = (path: string[]): string[] => {
  const expanded: string[] = ['root']
  let currentPath = ''

  for (const segment of path) {
    currentPath = currentPath ? `${currentPath}/${segment}` : segment
    expanded.push(currentPath)
  }

  return expanded
}

export const mergeExpanded = (existing: string[], newItems: string[]): string[] => {
  const set = new Set(existing)
  newItems.forEach((item) => set.add(item))
  return Array.from(set)
}

export const joinPath = (path: string[]): string => path.join('/')

export const joinExpandedItems = (items: string[]): string => items.join('|')
