'use client'

import { type ReactNode, useCallback, useMemo } from 'react'

import { Tooltip } from '@graftcode/design-system'

import { methodInfoStyles } from '@/core/components/MethodInfoBlock'
import { useTypeUsageGraftabilityIssues } from '@/core/components/TypeGraftabilityHint'
import { useLibraries } from '@/core/hooks'
import { useCodeStore, useNavigationStore } from '@/core/stores'
import type { TypeUsage } from '@/core/types/library.type'
import { getPathForTypeName } from '@/core/utils/getPathForTypeName'
import { getGraftabilityIssueSummary } from '@/core/utils/graftability/formatGraftabilityIssue'
import { renderTypeUsage } from '@/core/utils/mappers/formatTypeUsage'
import { translateTypeName } from '@/core/utils/translateTypeName'
import { TYPE_GRAFTABILITY_HINT_TEST_IDS, TYPE_LINK_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './TypeLink.module.scss'

const valueTypeClassName = methodInfoStyles.valueType

type Props = {
  typeName?: string
  typeUsage?: TypeUsage
  className?: string
}

function buildTypeClassName(className?: string, unsupported?: boolean) {
  return [valueTypeClassName, className, unsupported ? methodInfoStyles.valueTypeUnsupported : undefined]
    .filter(Boolean)
    .join(' ')
}

export function TypeLink({ typeName, typeUsage, className }: Props) {
  const { libraries } = useLibraries()
  const navigateTo = useNavigationStore((s) => s.navigateTo)
  const selectedTechnology = useCodeStore((s) => s.selectedTechnology)
  const issues = useTypeUsageGraftabilityIssues(typeUsage)

  const rawLabel = typeof typeName === 'string' ? typeName : ''
  const displayLabel = useMemo(() => {
    if (typeUsage) return renderTypeUsage(typeUsage, selectedTechnology)
    return translateTypeName(rawLabel, selectedTechnology)
  }, [typeUsage, rawLabel, selectedTechnology])

  const path = useMemo(() => getPathForTypeName(libraries ?? {}, rawLabel), [libraries, rawLabel])
  const handleClick = useCallback(() => {
    if (path) {
      navigateTo(path)
    }
  }, [path, navigateTo])

  const unsupported = issues.length > 0
  const combinedClassName = buildTypeClassName(className, unsupported)
  const unsupportedProps = unsupported
    ? {
        'data-testid': TYPE_GRAFTABILITY_HINT_TEST_IDS.root,
        'aria-label': 'Type cannot be grafted',
      }
    : undefined

  const tooltip = unsupported ? issues.map((issue) => getGraftabilityIssueSummary(issue)).join(' ') : undefined

  const wrapWithTooltip = (node: ReactNode) => (tooltip ? <Tooltip content={tooltip}>{node}</Tooltip> : node)

  if (!displayLabel.trim() || !path) {
    const content = (
      <span data-testid={TYPE_LINK_TEST_IDS.root} className={combinedClassName} {...unsupportedProps}>
        {displayLabel}
      </span>
    )
    return wrapWithTooltip(content)
  }

  const content = (
    <button
      type="button"
      className={`${styles.resetButton} ${combinedClassName}`}
      onClick={handleClick}
      title={unsupported ? undefined : `Go to ${rawLabel}`}
      {...unsupportedProps}
    >
      {displayLabel}
    </button>
  )

  return wrapWithTooltip(content)
}
