import type { ReactNode } from 'react'

import { COMMENT_RICH_TEXT_TEST_IDS } from '@/core/vision-test-ids.const'

import { parseCommentMarkup } from './parseCommentMarkup'

import styles from './CommentRichText.module.scss'

interface CommentRichTextProps {
  text: string
  className?: string
}

export function CommentRichText({ text, className }: CommentRichTextProps) {
  const paragraphs = text.split(/\n\n+/).filter((paragraph) => paragraph.trim().length > 0)

  return (
    <div
      data-testid={COMMENT_RICH_TEXT_TEST_IDS.root}
      className={className ? `${styles.richText} ${className}` : styles.richText}
    >
      {paragraphs.map((paragraph) => (
        <p key={paragraph} className={styles.paragraph}>
          {parseCommentMarkup(paragraph)}
        </p>
      ))}
    </div>
  )
}

export function renderCommentLines(text: string): ReactNode {
  const lines = text.split('\n')

  return lines.map((line, index) => (
    <span key={`${index}-${line}`} className={styles.line}>
      {parseCommentMarkup(line)}
      {index < lines.length - 1 ? <br /> : null}
    </span>
  ))
}
