import { MethodDetailItemRow } from '@/core/components/MethodDetailItemRow'
import { MethodInfoBlock } from '@/core/components/MethodInfoBlock'
import type { CommentReturnDoc } from '@/core/types/comment-doc.type'
import type { TypeUsage } from '@/core/types/library.type'
import { METHOD_RETURNS_TEST_IDS } from '@/core/vision-test-ids.const'

interface MethodReturnsProps {
  returns?: string
  returnTypeUsage?: TypeUsage
  commentReturn?: CommentReturnDoc
}

export function MethodReturns({ returns, returnTypeUsage, commentReturn }: MethodReturnsProps) {
  const typeName = returns ?? commentReturn?.rawType ?? commentReturn?.normalizedType
  const description = commentReturn?.description

  if (!typeName && !description) {
    return null
  }

  return (
    <div data-testid={METHOD_RETURNS_TEST_IDS.root}>
      <MethodInfoBlock title="Returns" layout="full" contentSurface={false}>
        <MethodDetailItemRow typeName={typeName} typeUsage={returnTypeUsage} description={description} />
      </MethodInfoBlock>
    </div>
  )
}
