'use client'

import { create } from 'zustand'
import { devtools } from 'zustand/middleware'

import { VisionStoreDevtoolsName } from '../vision-store-names.const'

import { createNavigationActions } from './navigation.actions'
import { createUseExpandedItems, createUseNavigationPath, createUseOpenAccordions } from './navigation.selector'
import { navigationInitialState } from './navigation.slice'
import type { NavigationStore } from './navigation.type'
import { initNavigationUrlSync } from './navigation-url-sync.utils'

export const useNavigationStore = create<NavigationStore>()(
  devtools(
    (set, get) => ({
      ...navigationInitialState,
      ...createNavigationActions(set, get),
    }),
    { name: VisionStoreDevtoolsName.Navigation }
  )
)

export const initUrlSync = () => initNavigationUrlSync(useNavigationStore)

/** Current navigation path (string-compared internally for reliable change detection) */
export const useNavigationPath = createUseNavigationPath(useNavigationStore)

/** Expanded tree items (string-compared internally for reliable change detection) */
export const useExpandedItems = createUseExpandedItems(useNavigationStore)

/** Open accordions (string-compared internally for reliable change detection) */
export const useOpenAccordions = createUseOpenAccordions(useNavigationStore)
