import type { ReactNode } from 'react'

import { methodInfoStyles } from '@/core/components/MethodInfoBlock'
import { COMMENT_RICH_TEXT_TEST_IDS } from '@/core/vision-test-ids.const'

const MARKUP_PATTERN = /(\{\{ref:[^}]+\}\}|\{\{code:[^}]+\}\})/g

function parseMarkupToken(token: string): ReactNode {
  if (token.startsWith('{{ref:')) {
    const target = token.slice('{{ref:'.length, -2).trim()
    return (
      <span key={token} data-testid={COMMENT_RICH_TEXT_TEST_IDS.markup} className={methodInfoStyles.valueType}>
        {target}
      </span>
    )
  }

  if (token.startsWith('{{code:')) {
    const expr = token.slice('{{code:'.length, -2).trim()
    return (
      <span key={token} data-testid={COMMENT_RICH_TEXT_TEST_IDS.markup} className={methodInfoStyles.valueType}>
        {expr}
      </span>
    )
  }

  return token
}

export function parseCommentMarkup(text: string): ReactNode[] {
  const parts = text.split(MARKUP_PATTERN).filter((part) => part.length > 0)

  return parts.map((part, index) => {
    if (part.startsWith('{{')) {
      return <span key={`${index}-${part}`}>{parseMarkupToken(part)}</span>
    }
    return <span key={`${index}-text`}>{part}</span>
  })
}
