import type { ReactNode } from 'react'

import { PropertiesTag } from '@graftcode/design-system'

import { VisionNotSupportedTag } from '@/core/components/VisionNotSupportedTag'
import { getBadgeType } from '@/core/utils/getBadgeType'
import { getPropertiesTagVariant } from '@/core/utils/getPropertiesTagVariant'

import styles from './createTitleWithBadge.module.scss'

export function createCallableAccordionTitle(title: ReactNode, badge?: string, showNotSupportedTag = false): ReactNode {
  const badgeVariant = badge ? getPropertiesTagVariant(getBadgeType(badge)) : undefined

  if (!badge && !showNotSupportedTag) {
    return title
  }

  return (
    <div className={styles.titleWithBadge}>
      <span className={styles.title}>{title}</span>
      <div className={styles.badges}>
        {showNotSupportedTag ? <VisionNotSupportedTag className="accordion__not-supported-tag" /> : null}
        {badge && badgeVariant ? (
          <PropertiesTag variant={badgeVariant} withoutIcon className="accordion__badge">
            {badge}
          </PropertiesTag>
        ) : null}
      </div>
    </div>
  )
}
