import { GATEWAY_USER_SETTINGS_STORAGE_KEY } from '@/core/utils/gateway-user-settings.const'
import type { GatewayUserSettings } from '@/core/utils/gateway-user-settings.interface'

export function saveGatewayUserSettings(settings: GatewayUserSettings): void {
  if (typeof window === 'undefined') {
    return
  }

  try {
    localStorage.setItem(GATEWAY_USER_SETTINGS_STORAGE_KEY, JSON.stringify(settings))
  } catch {
    // localStorage unavailable (incognito, quota exceeded)
  }
}
