import { useEffect } from 'react'

import { selectGatewayUserSettings } from '@/core/stores/gateway-settings/gateway-settings.selector'
import { useGatewaySettingsStore } from '@/core/stores/gateway-settings/gateway-settings.store'

export function useGatewayUserSettings() {
  const settings = useGatewaySettingsStore(selectGatewayUserSettings)
  const hydrate = useGatewaySettingsStore((state) => state.hydrate)
  const applyGatewaySettings = useGatewaySettingsStore((state) => state.applyGatewaySettings)
  const resetGatewaySettings = useGatewaySettingsStore((state) => state.resetGatewaySettings)

  useEffect(() => {
    hydrate()
  }, [hydrate])

  return {
    gatewaySettings: settings,
    applyGatewaySettings,
    resetGatewaySettings,
  }
}
