import { MethodDetailItemRow } from '@/core/components/MethodDetailItemRow'
import { MethodInfoBlock } from '@/core/components/MethodInfoBlock'
import type { ParameterData } from '@/core/types/library.type'
import { METHOD_PARAMETERS_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodParameters.module.scss'

interface MethodParametersProps {
  parameters: ParameterData[]
}

export function MethodParameters({ parameters }: MethodParametersProps) {
  if (parameters.length === 0) {
    return null
  }

  return (
    <MethodInfoBlock title="Parameters" layout="full" contentSurface={false}>
      <div data-testid={METHOD_PARAMETERS_TEST_IDS.root} className={styles.list}>
        {parameters.map((parameter) => (
          <MethodDetailItemRow
            key={parameter.name}
            name={parameter.name}
            typeName={parameter.type}
            typeUsage={parameter.typeUsage}
            description={parameter.description}
          />
        ))}
      </div>
    </MethodInfoBlock>
  )
}
