import type { VisionLocationMetadata } from '@/core/hooks/useRegisterVisionUrl/use-register-vision-url.interface'

export const collectVisionLocationMetadata = (): VisionLocationMetadata | null => {
  if (typeof window === 'undefined') {
    return null
  }

  const { origin, hostname, protocol, port, pathname, search } = window.location

  return {
    origin,
    hostname,
    protocol,
    port,
    pathname,
    href: `${origin}${pathname}${search}`,
  }
}
