'use client'

import { useMemo } from 'react'

import type { NavigationStore } from './navigation.type'

// String selectors give reliable change detection for array-backed state
export const selectPathString = (state: NavigationStore) => state.pathString
export const selectExpandedItemsString = (state: NavigationStore) => state.expandedItemsString
export const selectOpenAccordionsString = (state: NavigationStore) => state.openAccordionsString

export const selectPath = (state: NavigationStore) => state.path
export const selectExpandedItems = (state: NavigationStore) => state.expandedItems
export const selectOpenAccordions = (state: NavigationStore) => state.openAccordions

type UseStore = <T>(selector: (state: NavigationStore) => T) => T

export const createUseNavigationPath = (useStore: UseStore) => () => {
  const pathString = useStore(selectPathString)
  return useMemo(() => (pathString ? pathString.split('/') : []), [pathString])
}

export const createUseExpandedItems = (useStore: UseStore) => () => {
  const expandedString = useStore(selectExpandedItemsString)
  return useMemo(() => (expandedString ? expandedString.split('|') : []), [expandedString])
}

export const createUseOpenAccordions = (useStore: UseStore) => () => {
  const accordionsString = useStore(selectOpenAccordionsString)
  return useMemo(() => (accordionsString ? accordionsString.split('|') : []), [accordionsString])
}
