import type { ClassData, ConstructorData } from '@/core/types/library.type'

import { analyzeTypeUsageGraftability } from './analyzeTypeUsageGraftability'
import type { GraftabilityAnalysisOptions, GraftabilityIssue } from './types'

export function analyzeConstructorGraftability(
  constructor: ConstructorData,
  classData: ClassData,
  analysisOptions: GraftabilityAnalysisOptions
): GraftabilityIssue[] {
  const classFqn = `${classData.namespace}.${classData.name}`
  const issues: GraftabilityIssue[] = []

  for (const parameter of constructor.parameters) {
    const parameterAnalysis = analyzeTypeUsageGraftability(parameter.typeUsage, analysisOptions)
    for (const issue of parameterAnalysis.issues) {
      issues.push({
        ...issue,
        memberName: parameter.name,
        memberKind: 'constructor-parameter',
        className: classData.name,
        classFqn,
      })
    }
  }

  return issues
}
