import { ConstructorCardContent } from '@/core/components/Card/components/ConstructorCardContent'
import { MethodCardHeader } from '@/core/components/MethodCardHeader'
import { createNavigationCardItem } from '@/core/hooks/useCardNavigation/utils/createNavigationCardItem'
import { getBadgeLabel } from '@/core/hooks/useCardNavigation/utils/getBadgeLabel'
import { getParameterNamesSummary } from '@/core/hooks/useCardNavigation/utils/getParameterNamesSummary'
import type { ClassData, ConstructorData, LibraryData } from '@/core/types/library.type'
import {
  analyzeConstructorGraftability,
  buildHostedTypeFqns,
  buildHostingLibraryContext,
} from '@/core/utils/graftability'

interface BuildConstructorEntriesParams {
  classData: ClassData
  library: LibraryData
  openAccordions: string[]
  onAccordionToggle: (itemId: string) => void
}

export const buildConstructorEntries = ({
  classData,
  library,
  openAccordions,
  onAccordionToggle,
}: BuildConstructorEntriesParams) => {
  const analysisOptions = {
    hostedTypeFqns: buildHostedTypeFqns(library),
    hostingLibraryContext: buildHostingLibraryContext(library),
  }

  return classData.constructors
    ? Object.entries(classData.constructors).map(([constructorKey, constructor]: [string, ConstructorData]) => {
        const badge = getBadgeLabel(constructor.type)
        const graftabilityIssues = analyzeConstructorGraftability(constructor, classData, analysisOptions)
        const title = (
          <MethodCardHeader name={constructor.name} parameters={constructor.parameters} comment={constructor.comment} />
        )

        const content = (
          <ConstructorCardContent
            constructor={constructor}
            constructorKey={constructorKey}
            classData={classData}
            runtimeName={library.runtimeName}
            graftabilityIssues={graftabilityIssues}
          />
        )

        return createNavigationCardItem({
          id: constructorKey,
          title,
          name: constructor.name,
          badge,
          description: getParameterNamesSummary(constructor.parameters),
          content,
          isOpen: openAccordions.includes(constructorKey),
          onAccordionToggle,
          graftabilityIssues,
        })
      })
    : []
}
