'use client'
import { useMemo } from 'react'

import type { CodeSnippetProps } from '@graftcode/design-system'
import { CodeSnippet } from '@graftcode/design-system'

import { getLanguageForPM } from '@common/utils/technology'

import { NoTechnologyPlaceholder } from '@/core/components/Card/components/NoTechnologyPlaceholder'
import { MethodParameters } from '@/core/components/MethodParameters'
import { MethodReturns } from '@/core/components/MethodReturns'
import { MethodSignature } from '@/core/components/MethodSignature'
import { MethodThrows } from '@/core/components/MethodThrows'
import { MethodUnsupportedTypeAlert } from '@/core/components/MethodUnsupportedTypeAlert'
import { Runtime } from '@/core/enums/runtime.enum'
import { useMethodExecution } from '@/core/hooks'
import type { ClassData, MethodData } from '@/core/types/library.type'
import type { GraftabilityIssue } from '@/core/utils/graftability'
import { METHOD_CARD_CONTENT_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodCardContent.module.scss'

interface MethodCardContentProps {
  methodKey: string
  method: MethodData
  classData: ClassData
  runtimeName: Runtime
  graftabilityIssues?: GraftabilityIssue[]
}

export function MethodCardContent({
  method,
  methodKey,
  classData,
  runtimeName,
  graftabilityIssues = [],
}: MethodCardContentProps) {
  const {
    code,
    executionLogs,
    valueMap,
    variableCode,
    selectedTechnology,
    snippetTechnology,
    constructors,
    shouldShowConstructorSelector,
    selectedConstructorId,
    constructorValueMap,
    handleValueChange,
    handleRun,
    handleClear,
    handleTryIt,
    onConstructorChange,
    onConstructorValueChange,
  } = useMethodExecution({ method, methodKey, classData, runtimeName })

  const language = useMemo(
    (): string | undefined => (snippetTechnology ? getLanguageForPM(snippetTechnology) : undefined),
    [snippetTechnology]
  )

  const snippetKey = useMemo(
    () => `method-${methodKey}-${selectedTechnology || 'none'}-${snippetTechnology || 'none'}`,
    [methodKey, selectedTechnology, snippetTechnology]
  )

  const throws = method.comment?.throws ?? []

  return (
    <div data-testid={METHOD_CARD_CONTENT_TEST_IDS.root} className={styles.method}>
      <MethodUnsupportedTypeAlert issues={graftabilityIssues} />
      <MethodSignature
        name={method.name}
        returns={method.returns}
        returnTypeUsage={method.returnTypeUsage}
        parameters={method.parameters}
      />

      <MethodParameters parameters={method.parameters} />

      <MethodReturns
        returns={method.returns}
        returnTypeUsage={method.returnTypeUsage}
        commentReturn={method.comment?.returns}
      />

      <MethodThrows throws={throws} />

      <div className={styles.exampleSection}>
        <CodeSnippet
          key={snippetKey}
          {...({
            className: styles.exampleContent,
            code,
            contentVariant: 'advanced',
            isExampleMode: true,
            language,
            noTechnologyPlaceholder: <NoTechnologyPlaceholder />,
            exampleParameters: method.parameters,
            valueMap,
            variableCode,
            logs: executionLogs,
            onExampleRun: handleRun,
            onExampleClear: handleClear,
            onExampleValueChange: handleValueChange,
            onTryItToggle: handleTryIt,
            ...(shouldShowConstructorSelector && constructors
              ? {
                  constructors,
                  selectedConstructorId,
                  constructorValueMap,
                  onConstructorChange,
                  onConstructorValueChange,
                }
              : {}),
          } as CodeSnippetProps & { onTryItToggle?: () => void })}
        />
      </div>
    </div>
  )
}
