'use client'

import { useMemo } from 'react'

import { useLibraries } from '@/core/hooks'
import { useCodeStore, useNavigationPath } from '@/core/stores'
import type { TypeUsage } from '@/core/types/library.type'
import {
  analyzeTypeUsageGraftability,
  buildHostedTypeFqns,
  buildHostingLibraryContext,
  type GraftabilityIssue,
} from '@/core/utils/graftability'

export function useTypeUsageGraftabilityIssues(typeUsage?: TypeUsage): GraftabilityIssue[] {
  const selectedTechnology = useCodeStore((state) => state.selectedTechnology)
  const navigationPath = useNavigationPath()
  const { libraries } = useLibraries()

  const analysisOptions = useMemo(() => {
    const libraryName = navigationPath[0]
    const libraryData = libraryName && libraries ? libraries[libraryName] : undefined
    if (!libraryData) return undefined
    return {
      hostedTypeFqns: buildHostedTypeFqns(libraryData),
      hostingLibraryContext: buildHostingLibraryContext(libraryData),
    }
  }, [navigationPath, libraries])

  return useMemo(() => {
    if (!typeUsage) return []
    return analyzeTypeUsageGraftability(typeUsage, {
      technology: selectedTechnology,
      ...analysisOptions,
    }).issues
  }, [typeUsage, selectedTechnology, analysisOptions])
}
