import { Icon, IconComponent } from '@graftcode/design-system'

import type { GraftabilityIssue } from '@/core/utils/graftability'
import { getUnsupportedMemberAlertModel } from '@/core/utils/graftability/getUnsupportedMemberAlertModel'
import { METHOD_UNSUPPORTED_TYPE_ALERT_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodUnsupportedTypeAlert.module.scss'

interface MethodUnsupportedTypeAlertProps {
  issues: GraftabilityIssue[]
}

export function MethodUnsupportedTypeAlert({ issues }: MethodUnsupportedTypeAlertProps) {
  const model = getUnsupportedMemberAlertModel(issues)

  if (!model) {
    return null
  }

  return (
    <div data-testid={METHOD_UNSUPPORTED_TYPE_ALERT_TEST_IDS.root} className={styles.root}>
      <IconComponent icon={Icon.ErrorCircleFilled} size={20} className={styles.icon} aria-hidden />
      <div className={styles.content}>
        <div className={styles.headlineRow}>
          <span className={styles.headline}>{model.headline}</span>
          {model.typeLabels.map((typeLabel) => (
            <span key={typeLabel} className={styles.typeChip}>
              {typeLabel}
            </span>
          ))}
        </div>
        <p className={styles.description}>{model.description}</p>
      </div>
    </div>
  )
}
