'use client'

import { create } from 'zustand'
import { devtools } from 'zustand/middleware'

import { VisionStoreDevtoolsName } from '../vision-store-names.const'

import { createLibraryActions } from './libraries.actions'
import { librariesInitialState } from './libraries.slice'
import type { LibraryStore } from './libraries.type'

export const useLibraryStore = create<LibraryStore>()(
  devtools(
    (set, get) => ({
      ...librariesInitialState,
      ...createLibraryActions(set, get),
    }),
    { name: VisionStoreDevtoolsName.Libraries }
  )
)
