import type { PropsWithChildren } from 'react'

import { METHOD_INFO_BLOCK_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodInfoBlock.module.scss'

interface MethodInfoBlockProps extends PropsWithChildren {
  title: string
  variant?: 'column' | 'row'
  layout?: 'compact' | 'full'
  contentSurface?: boolean
  className?: string
}

export function MethodInfoBlock({
  title,
  variant = 'column',
  layout = 'compact',
  contentSurface = true,
  children,
  className,
}: MethodInfoBlockProps) {
  const contentClass = variant === 'row' ? styles.contentRow : styles.contentColumn
  const surfaceClass = contentSurface ? contentClass : styles.contentPlain
  const blockClass = layout === 'full' ? `${styles.block} ${styles.blockFull}` : styles.block

  return (
    <div data-testid={METHOD_INFO_BLOCK_TEST_IDS.root} className={`${blockClass} ${className ?? ''}`}>
      <div className={styles.title}>{title}</div>
      <div className={surfaceClass}>{children}</div>
    </div>
  )
}

// Export styles for use in child components
export { styles as methodInfoStyles }
