import { renderCommentLines } from '@/core/components/CommentRichText'
import { methodInfoStyles } from '@/core/components/MethodInfoBlock'
import { TypeLink } from '@/core/components/TypeLink'
import type { TypeUsage } from '@/core/types/library.type'
import { METHOD_DETAIL_ITEM_ROW_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodDetailItemRow.module.scss'

interface MethodDetailItemRowProps {
  name?: string
  typeName?: string
  typeUsage?: TypeUsage
  description?: string
}

export function MethodDetailItemRow({ name, typeName, typeUsage, description }: MethodDetailItemRowProps) {
  const hasDescription = Boolean(description?.trim())
  const showType = Boolean(typeName?.trim())

  return (
    <div data-testid={METHOD_DETAIL_ITEM_ROW_TEST_IDS.root} className={styles.surface}>
      <div className={styles.row}>
        {name ? <span className={methodInfoStyles.valueName}>{name}:</span> : null}
        {showType ? (
          <TypeLink typeName={typeName} typeUsage={typeUsage} className={methodInfoStyles.valueType} />
        ) : null}
        {hasDescription ? (
          <span className={styles.description}>
            <span className={styles.descriptionPrefix}>-</span>
            {renderCommentLines(description ?? '')}
          </span>
        ) : null}
      </div>
    </div>
  )
}
