'use client'

import { create } from 'zustand'
import { devtools } from 'zustand/middleware'

import { clearGatewayUserSettings } from '@/core/utils/clearGatewayUserSettings'
import { DEFAULT_GATEWAY_USER_SETTINGS } from '@/core/utils/gateway-user-settings.const'
import { loadGatewayUserSettings } from '@/core/utils/loadGatewayUserSettings'
import { saveGatewayUserSettings } from '@/core/utils/saveGatewayUserSettings'

import { VisionStoreDevtoolsName } from '../vision-store-names.const'

import { gatewaySettingsInitialState } from './gateway-settings.slice'
import type { GatewaySettingsStore } from './gateway-settings.type'

export const useGatewaySettingsStore = create<GatewaySettingsStore>()(
  devtools(
    (set, get) => ({
      ...gatewaySettingsInitialState,
      hydrate: () => {
        if (get().hydrated || typeof window === 'undefined') {
          return
        }

        set({
          settings: loadGatewayUserSettings(),
          hydrated: true,
        })
      },
      applyGatewaySettings: (settings) => {
        saveGatewayUserSettings(settings)
        set({ settings, hydrated: true })
      },
      resetGatewaySettings: () => {
        clearGatewayUserSettings()
        set({ settings: DEFAULT_GATEWAY_USER_SETTINGS, hydrated: true })
      },
    }),
    { name: VisionStoreDevtoolsName.GatewaySettings }
  )
)
