import { TreeItem } from '@graftcode/design-system'

import { ClassData, ConstructorData, MethodData } from '@/core/types/library.type'
import { createTreeBadgeContent } from '@/core/utils/createTreeBadgeContent'
import {
  analyzeConstructorGraftability,
  analyzeMethodGraftability,
  type GraftabilityAnalysisOptions,
} from '@/core/utils/graftability'

import { getEnumKeyName } from '../getEnumKeyName'

import { isConstructorTreeItem } from './isConstructorTreeItem'

const BADGE_LABEL_MAP: Record<string, string> = {
  CONSTRUCTOR: 'Constructor',
  OVERLOADED_CONSTRUCTOR: 'Constructor',
  INSTANCE_METHOD: 'Instance Method',
  OVERLOADED_INSTANCE_METHOD: 'Instance Method',
  STATIC_METHOD: 'Static Method',
  OVERLOADED_STATIC_METHOD: 'Static Method',
  GLOBAL_METHOD: 'Global Method',
  OVERLOADED_GLOBAL_METHOD: 'Global Method',
}

const getBadgeLabel = (type: string | number): string | undefined => BADGE_LABEL_MAP[getEnumKeyName(type)]

/**
 * Maps MethodData or ConstructorData to a TreeItem: id, label, url hash, and optional badge (e.g. "Instance Method", "Constructor").
 *
 * @param itemKey - Optional key for overloaded constructors to ensure unique IDs
 */
export const mapClassItemToTreeItem = (
  item: MethodData | ConstructorData,
  parentPath: string,
  itemKey?: string,
  classData?: ClassData,
  analysisOptions?: GraftabilityAnalysisOptions
): TreeItem => {
  const uniqueId = itemKey || item.name
  const id = `${parentPath}/${uniqueId}`
  const badge = getBadgeLabel(item.type)

  const treeItem: TreeItem & { graftabilityIndicator?: 'type' | 'member' } = {
    id,
    label: item.name,
    url: `#${id}`,
  }

  if (badge) {
    treeItem.badge = createTreeBadgeContent(badge)
  }

  if (classData && analysisOptions) {
    const issues = isConstructorTreeItem(item)
      ? analyzeConstructorGraftability(item as ConstructorData, classData, analysisOptions)
      : analyzeMethodGraftability(item as MethodData, classData, analysisOptions)

    if (issues.length > 0) {
      treeItem.graftabilityIndicator = 'member'
    }
  }

  return treeItem as TreeItem
}
