import type {
  CommentDocData,
  CommentParameterDoc,
  CommentReturnDoc,
  CommentThrowDoc,
} from '@/core/types/comment-doc.type'
import { UnifiedGraftModelTypeKey } from '@/core/vision-graft-model.const'

import { getUnifiedGraftModelType } from '../getUnifiedGraftModelType'

import { findPayloadChildByType } from './findPayloadChildByType'
import { hasPayload } from './formatTypeUsage/nodeHelpers'
import type { NodeLike } from './formatTypeUsage/types'
import { safeString } from './safeString'

function mapCommentParameter(node: NodeLike): CommentParameterDoc {
  const [name, rawType, normalizedType, description] = node.payload

  return {
    name: safeString(name),
    rawType: safeString(rawType) || undefined,
    normalizedType: safeString(normalizedType) || undefined,
    description: safeString(description) || undefined,
  }
}

function mapCommentParametersArray(node: NodeLike): CommentParameterDoc[] {
  return node.payload
    .filter(
      (child) => hasPayload(child) && getUnifiedGraftModelType(child) === UnifiedGraftModelTypeKey.COMMENT_PARAMETER
    )
    .map((child) => mapCommentParameter(child as NodeLike))
}

function mapCommentReturns(node: NodeLike): CommentReturnDoc {
  const [rawType, normalizedType, description] = node.payload

  return {
    rawType: safeString(rawType) || undefined,
    normalizedType: safeString(normalizedType) || undefined,
    description: safeString(description) || undefined,
  }
}

function mapCommentThrow(node: NodeLike): CommentThrowDoc {
  const [rawType, category, description] = node.payload

  return {
    rawType: safeString(rawType),
    category: safeString(category) || undefined,
    description: safeString(description) || undefined,
  }
}

function mapCommentThrowsArray(node: NodeLike): CommentThrowDoc[] {
  return node.payload
    .filter((child) => hasPayload(child) && getUnifiedGraftModelType(child) === UnifiedGraftModelTypeKey.COMMENT_THROW)
    .map((child) => mapCommentThrow(child as NodeLike))
    .filter((item) => item.rawType.length > 0)
}

function mapCommentDocNode(node: NodeLike): CommentDocData {
  const payload = node.payload
  const summaryNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_SUMMARY)
  const descriptionNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_DESCRIPTION)
  const parametersNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_PARAMETERS_ARRAY)
  const returnsNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_RETURNS)
  const throwsNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_THROWS_ARRAY)

  const summary = summaryNode ? safeString(summaryNode.payload[0]) : ''
  const description = descriptionNode ? safeString(descriptionNode.payload[0]) : ''

  const data: CommentDocData = {}

  if (summary) {
    data.summary = summary
  }
  if (description) {
    data.description = description
  }
  if (parametersNode) {
    const parameters = mapCommentParametersArray(parametersNode)
    if (parameters.length > 0) {
      data.parameters = parameters
    }
  }
  if (returnsNode) {
    const returns = mapCommentReturns(returnsNode)
    if (returns.description || returns.rawType || returns.normalizedType) {
      data.returns = returns
    }
  }
  if (throwsNode) {
    const throws = mapCommentThrowsArray(throwsNode)
    if (throws.length > 0) {
      data.throws = throws
    }
  }

  return data
}

export function mapCommentDocFromMemberPayload(payload: unknown[]): CommentDocData | undefined {
  const commentDocNode = findPayloadChildByType(payload, UnifiedGraftModelTypeKey.COMMENT_DOC)
  if (!commentDocNode) {
    return undefined
  }

  const mapped = mapCommentDocNode(commentDocNode)
  const hasContent =
    mapped.summary ||
    mapped.description ||
    (mapped.parameters?.length ?? 0) > 0 ||
    mapped.returns ||
    (mapped.throws?.length ?? 0) > 0

  return hasContent ? mapped : undefined
}

export function mergeParameterDescriptions<T extends { name: string; description?: string }>(
  parameters: T[],
  commentParameters?: CommentParameterDoc[]
): T[] {
  if (!commentParameters?.length) {
    return parameters
  }

  const descriptionByName = new Map(
    commentParameters.filter((p) => p.description).map((p) => [p.name, p.description as string])
  )

  if (descriptionByName.size === 0) {
    return parameters
  }

  return parameters.map((parameter) => {
    const description = descriptionByName.get(parameter.name)
    if (!description) {
      return parameter
    }
    return { ...parameter, description }
  })
}

export { mapCommentDocNode }
