import type {
  BuildInstanceExecutionParamsParams,
  BuildInstanceExecutionParamsResult,
} from '@/core/hooks/utils/execution.interface'

import { coerceParametersFromMap } from './coerceParametersFromMap'

export const buildInstanceExecutionParams = ({
  isStatic,
  classData,
  selectedConstructorId,
  constructorValueMap,
}: BuildInstanceExecutionParamsParams): BuildInstanceExecutionParamsResult => {
  if (isStatic || !selectedConstructorId || !classData.constructors) {
    return { instanceParams: [] }
  }

  const selectedConstructor = classData.constructors[selectedConstructorId]
  if (!selectedConstructor) {
    return { instanceParams: [] }
  }

  return {
    instanceParams: coerceParametersFromMap({
      parameters: selectedConstructor.parameters,
      valueMap: constructorValueMap,
    }),
    constructorKey: selectedConstructorId,
  }
}
