import type { RegisterVisionUrlPayload } from '@/core/api/api.interface'
import { postJson } from '@/core/utils/fetch'
import { GATEWAY_ROUTE_VISION_REGISTER_URL } from '@/core/vision-core.const'

import { buildUrl, type GatewayConfig } from './libraries.api'

export const registerVisionUrl = async (config: GatewayConfig, payload: RegisterVisionUrlPayload): Promise<void> => {
  const url = `${buildUrl(config)}/${GATEWAY_ROUTE_VISION_REGISTER_URL}`
  await postJson(url, payload)
}
