import type { LibraryStore } from './libraries.type'

export const selectLibraries = (state: LibraryStore) => state.libraries

export const selectLibraryRuntimeSnapshot = (state: LibraryStore) => ({
  libraries: state.libraries,
  gateway: state.gateway,
  gatewayPath: state.gatewayPath,
  gatewayPort: state.gatewayPort,
  gatewayWsPort: state.gatewayWsPort,
  gatewayMcpPort: state.gatewayMcpPort,
  isSecured: state.isSecured,
  guid: state.guid,
  registry: state.registry,
  projectName: state.projectName,
  gsmuEndpoint: state.gsmuEndpoint,
})
