import { getUnifiedGraftModelType } from '@/core/utils/getUnifiedGraftModelType'

import { hasPayload } from './formatTypeUsage/nodeHelpers'
import type { NodeLike } from './formatTypeUsage/types'

export function findPayloadChildByType(payload: unknown[], typeKey: string): NodeLike | undefined {
  const match = payload.find((item) => hasPayload(item) && getUnifiedGraftModelType(item) === typeKey) as
    | NodeLike
    | undefined

  return match
}
