import type { ClassData, LibraryData } from '@/core/types/library.type'

import { analyzeConstructorGraftability } from './analyzeConstructorGraftability'
import { analyzeMethodGraftability } from './analyzeLibraryGraftability'
import { buildGraftabilityAnalysisOptions } from './buildGraftabilityAnalysisOptions'

export function countNonGraftableCallables(libraryData: LibraryData): number {
  const analysisOptions = buildGraftabilityAnalysisOptions(libraryData)
  let count = 0

  const visitClass = (classData: ClassData): void => {
    for (const method of Object.values(classData.methods ?? {})) {
      if (analyzeMethodGraftability(method, classData, analysisOptions).length > 0) {
        count += 1
      }
    }

    for (const constructor of Object.values(classData.constructors ?? {})) {
      if (analyzeConstructorGraftability(constructor, classData, analysisOptions).length > 0) {
        count += 1
      }
    }

    for (const child of Object.values(classData.children ?? {})) {
      visitClass(child)
    }
  }

  for (const classData of Object.values(libraryData.classes ?? {})) {
    visitClass(classData)
  }

  return count
}
