import type { ReactNode } from 'react'

import { type AccordionProps } from '@graftcode/design-system'

/**
 * Builds an AccordionProps object for the design-system accordion: id, title slot, content, and toggle handler.
 */
export const createAccordion = (
  id: string,
  titleSlot: ReactNode,
  content: ReactNode,
  isOpen: boolean,
  onToggle: (itemId: string) => void
): AccordionProps => ({
  id,
  titleSlot,
  content,
  onCollapseChange: () => onToggle(id),
})
