'use client'

import type { NavigationBoundStore } from './navigation.type'

let urlSyncInitialized = false
let prevPathString = ''

/**
 * Bidirectional sync between navigation state and URL hash.
 * Call once on the client side.
 */
export const initNavigationUrlSync = (store: NavigationBoundStore) => {
  if (typeof window === 'undefined' || urlSyncInitialized) return

  urlSyncInitialized = true
  prevPathString = store.getState().pathString

  store.subscribe((state) => {
    if (state.pathString !== prevPathString) {
      prevPathString = state.pathString
      const currentHash = window.location.hash.slice(1)
      if (state.pathString !== currentHash) {
        window.history.replaceState(null, '', state.pathString ? `#${state.pathString}` : window.location.pathname)
      }
    }
  })

  // Always sync on initial load (even with empty hash) so 'root' is expanded by default
  const initialHash = window.location.hash.slice(1)
  store.getState().syncFromUrl(initialHash)

  window.addEventListener('popstate', () => {
    const hash = window.location.hash.slice(1)
    store.getState().syncFromUrl(hash)
  })
}

/** Reset URL sync state (useful for testing) */
export const resetUrlSync = () => {
  urlSyncInitialized = false
  prevPathString = ''
}
