import type { InvocationContext, RuntimeContext } from 'hypertube-nodejs-sdk'

import { getClassPath } from '@/core/libraries-runtime/getClassPath'
import { getFieldReadLabel } from '@/core/libraries-runtime/getFieldReadLabel'
import type { ExecutableMember, ExecuteMemberParams, Library, LibraryData } from '@/core/types/library.type'
import { isGlobalMethodType } from '@/core/utils/isGlobalMethodType'
import { mapLibrary } from '@/core/utils/mappers/mapLibrary'
import { UnifiedGraftModelTypeKey } from '@/core/vision-graft-model.const'

import type { LibraryStore } from './libraries.type'

export const mergeLibraries = (existing: Record<string, LibraryData>, libraries: Library[]) => ({
  ...existing,
  ...Object.fromEntries(
    libraries.map((lib) => {
      const mapped = mapLibrary(lib)
      return [mapped.id, mapped]
    })
  ),
})

export const appendLog = (state: LibraryStore, key: string, message: string) => ({
  ...state.logs,
  [key]: [...(state.logs[key] ?? []), message],
})

export function formatResultLogLine(formatted: string): string {
  return formatted.includes('\n') ? `Result:\n${formatted}` : `Result: ${formatted}`
}

export function formatExecutionError(error: unknown): string {
  const message = String(error ?? '')
  const isAssemblyLoad =
    message.includes('FileNotFoundException') ||
    message.includes('Could not load file or assembly') ||
    message.includes('Nie można odnaleźć określonego pliku')
  const hint = isAssemblyLoad
    ? ' This usually means a required assembly or package is not available in the execution environment (e.g. gateway).'
    : ''
  return `Error trying to execute ${message}${hint}`
}

export function getTypeContext(
  runtimeContext: RuntimeContext,
  runtimeName: ExecuteMemberParams['runtimeName'],
  classData: ExecuteMemberParams['classData']
): InvocationContext {
  return runtimeContext.getType(getClassPath(runtimeName, classData))
}

export function needsInstance(member: ExecutableMember): boolean {
  if (member.kind === 'constructor') return true
  if (member.kind === 'method') return !member.isStatic && !isGlobalMethodType(member.method.type)
  return member.field.type === UnifiedGraftModelTypeKey.INSTANCE_FIELD && !member.field.isStatic
}

export function isGlobalMember(member: ExecutableMember): boolean {
  if (member.kind === 'field') return member.field.type === UnifiedGraftModelTypeKey.GLOBAL_FIELD
  if (member.kind === 'method') return isGlobalMethodType(member.method.type)
  return false
}

function formatLogParam(value: unknown): string {
  if (typeof value === 'string') return value
  if (typeof value === 'number' || typeof value === 'boolean' || value === null) return String(value)
  try {
    return JSON.stringify(value)
  } catch {
    return String(value)
  }
}

export function formatInstanceLog(
  className: string,
  constructorKey: string | undefined,
  instanceParams: ReadonlyArray<unknown>
): string {
  const ctor = constructorKey ? ` [${constructorKey}]` : ''
  const params =
    instanceParams.length > 0
      ? ` with parameters: ${instanceParams.map(formatLogParam).join(', ')}`
      : ' without parameters'
  return `Creating instance of class ${className} with constructor${ctor}${params}`
}

export function formatActionLog(member: ExecutableMember, methodParams: ReadonlyArray<unknown>): string | undefined {
  if (member.kind === 'field') {
    return `Reading ${getFieldReadLabel(member.field)} ${member.field.name}`
  }

  if (member.kind === 'method') {
    const params =
      methodParams.length > 0 ? `with parameters: ${methodParams.map(formatLogParam).join(', ')}` : 'without parameters'
    return `Executing method ${member.method.name} [${member.methodKey}] ${params}`
  }

  return undefined
}
