export function getCodeSnippetLanguage(technologyId: string | undefined): string {
  if (!technologyId) return 'javascript'
  const map: Record<string, string> = {
    npm: 'javascript',
    nuget: 'csharp',
    netcore: 'csharp',
    maven: 'java',
    pypi: 'python',
    python: 'python',
    packagist: 'php',
    ruby: 'ruby',
  }
  return map[technologyId] ?? 'plainText'
}

