const ENV_VARIABLE_TEXT_TEMPLATE = 'name={graftName};runtime={runtime};host={protocol}://{gateway}/ws;stateless=true'

const ENV_VARIABLE_JSON_TEMPLATE = `{
  "configurations": {
    "{graftName}": {
      "runtime": "{runtime}",
      "host": "{protocol}://{gateway}/ws",
      "stateless": "true"
    }
  }
}`

const ENV_VARIABLE_YAML_TEMPLATE = `configurations:
  "{graftName}":
    runtime: {runtime}
    host: {protocol}://{gateway}/ws
    stateless: true`

const ENV_VARIABLE_DOTENV_TEMPLATE =
  '{graftConfigEnvVarName}="name={graftName};runtime={runtime};host={protocol}://{gateway}/ws;stateless=true"'

