import type { ConstructorData, MethodData } from '@/core/types/library.type'

import { getEnumKeyName } from '../getEnumKeyName'

const CONSTRUCTOR_TYPE_KEYS = new Set(['CONSTRUCTOR', 'OVERLOADED_CONSTRUCTOR'])

export function isConstructorTreeItem(item: MethodData | ConstructorData): boolean {
  return CONSTRUCTOR_TYPE_KEYS.has(getEnumKeyName(item.type))
}
