'use client'

import { CommentRichText } from '@/core/components/CommentRichText'
import { CallableTitle } from '@/core/hooks/useCardNavigation/components/CallableTitle/CallableTitle'
import type { CommentDocData } from '@/core/types/comment-doc.type'
import type { ParameterData } from '@/core/types/library.type'
import { METHOD_CARD_HEADER_TEST_IDS } from '@/core/vision-test-ids.const'

import styles from './MethodCardHeader.module.scss'

interface MethodCardHeaderProps {
  name: string
  parameters: ParameterData[]
  comment?: CommentDocData
}

export function MethodCardHeader({ name, parameters, comment }: MethodCardHeaderProps) {
  const headerText = comment?.summary ?? comment?.description
  const bodyText = comment?.summary && comment?.description ? comment.description : undefined

  return (
    <div data-testid={METHOD_CARD_HEADER_TEST_IDS.root} className={styles.header}>
      <CallableTitle name={name} parameters={parameters} />
      {headerText ? <CommentRichText text={headerText} className={styles.summary} /> : null}
      {bodyText ? <CommentRichText text={bodyText} className={styles.summary} /> : null}
    </div>
  )
}
